import {
  NotificationResult,
  SectionSnapshot,
  SendEmail,
  Subscriptions,
} from "./types";

const isOpen = (section: SectionSnapshot): boolean =>
  section.enrolledCount < section.capacity;

/**
 * Given the *previous* and *current* full snapshots from two consecutive
 * runs of the enrollment puller, notify every subscriber of a section that
 * just gained an open seat -- i.e. a section that was full last run and
 * has at least one open seat this run.
 *
 * A section that was already open last run and is still open this run
 * must NOT generate another notification (no duplicate spam while the
 * seat stays available). A section that closes and later reopens IS a
 * genuinely new transition and must notify again.
 *
 * A failed send must not prevent other sections/subscribers in the same
 * batch from being processed.
 *
 * Rules:
 *  - A section only qualifies if it was NOT open in `previousSnapshot` and
 *    IS open in `currentSnapshot` -- i.e. `!isOpen(previous) &&
 *    isOpen(current)`. Being open in both snapshots is not a transition and
 *    must not notify anyone.
 *  - A section present in `currentSnapshot` but absent from
 *    `previousSnapshot` has no prior state to compare against and should
 *    not be treated as a transition.
 *  - Look up each section's subscribers via `subscriptions[sectionId]`. A
 *    section with no entry (or an empty list) simply produces no results
 *    for that section -- do not throw and do not fabricate a result.
 *  - For every subscriber of a qualifying section, call `sendEmail` once
 *    and push one `NotificationResult` per attempt: `status: "sent"` if it
 *    resolves, `status: "failed"` with the error message if it rejects.
 *  - One subscriber's failed send must not stop the rest of that section's
 *    subscribers, or any other section's subscribers, from being
 *    processed in the same call.
 *
 * See impl/README.md for the exact test expectations.
 */
export async function processEnrollmentUpdate(
  previousSnapshot: SectionSnapshot[],
  currentSnapshot: SectionSnapshot[],
  subscriptions: Subscriptions,
  sendEmail: SendEmail
): Promise<NotificationResult[]> {
  throw new Error("not implemented");
}
